        global $wpdb;if (!self::agency()||!current_user_can('atlas_manage_event_sensitive')) return self::error('atlas_forbidden','Authorized prerequisite reviewer required.','بازبین مجاز پیش‌نیاز لازم است.',403);if (array_diff(array_keys($body),['decision','reason','evidence_reference'])||!in_array($body['decision']??'',['accepted','rejected'],true)||!self::reference($body['evidence_reference']??null)||!is_string($body['reason']??null)||trim($body['reason'])===''||strlen($body['reason'])>190) return self::error('atlas_invalid_prerequisite','Review evidence and reason required.','شواهد بازبینی و دلیل لازم است.');return self::write('event.attendee_review',$key,[$id,$body],function() use ($id,$body,$wpdb) { $row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('submissions').' WHERE id=%s FOR UPDATE',$id));if (!$row||$row->state!=='pending_review'||(int)$row->owner_id===get_current_user_id()) return self::error('atlas_event_conflict','Independent pending-submission review required.','بازبینی مستقل اطلاعات در انتظار لازم است.',409);if ($wpdb->update(self::table('submissions'),['state'=>$body['decision'],'reviewed_by'=>get_current_user_id(),'review_reference'=>$body['evidence_reference']],['id'=>$id])!==1) throw new RuntimeException('review');$occ=Atlas_Events::occurrence($row->occurrence_id);self::audit((int)$occ->org_id,'event.attendee_'.$body['decision'],$id,$body['reason']);return ['id'=>$id,'state'=>$body['decision']]; });
    }
    public static function prepare_attendees($event,$occ,$offer,$quantity,$user,$options,$now,$refs=[]) {
        global $wpdb;if (is_wp_error($event)) return $event;$form=self::active_form($occ->id,true);if (!$form) return empty($options['event_attendee_submission'])?$event:self::error('atlas_invalid_attendee_data','No current attendee form matches this reference.','فرم فعلی شرکت‌کننده با این مرجع تطابق ندارد.');$policy=self::policy_for($form,$occ,true);if (is_wp_error($policy)) return $policy;$id=$options['event_attendee_submission']??'';$row=self::uuid($id)?$wpdb->get_row($wpdb->prepare('SELECT * FROM '.self::table('submissions').' WHERE id=%s FOR UPDATE',$id)):null;if (!$row||$row->form_id!==$form->id||$row->occurrence_id!==$occ->id||(int)$row->owner_id!==$user||(int)$row->quantity!==$quantity||!in_array($row->state,['ready','accepted'],true)||$row->booking_id!==''||$row->retain_until<=$now) return self::error('atlas_event_attendee_required','Complete the current private attendee form and any prerequisite review before reserving.','پیش از رزرو فرم خصوصی فعلی و بازبینی پیش‌نیاز را کامل کنید.',409);$data=self::decrypt($row->encrypted_payload);if (!is_array($data)) return self::error('atlas_event_encryption_unavailable','Protected attendee data unavailable.','اطلاعات محافظت‌شده شرکت‌کننده در دسترس نیست.',503);$s=json_decode($form->payload,true);$declared=array_column($data['attendees'],'traveler_ref');$actual=array_values($refs);if (($s['require_traveler']||$actual)&&$declared!==$actual) return self::error('atlas_invalid_participant','Attendee references must exactly match the core-validated travelers.','شناسه‌های شرکت‌کنندگان باید دقیقاً با مسافران اعتبارسنجی‌شده تطابق داشته باشند.');$event['attendee_form']=['submission_id'=>$row->id,'form_id'=>$form->id,'version'=>(int)$form->version,'schema_reference'=>$s['schema_reference']];return $event;
