    public static function purge_due($reason) {
        global $wpdb;if (!self::agency()||!current_user_can('atlas_manage_event_sensitive')||!is_string($reason)||trim($reason)===''||strlen($reason)>190) return self::error('atlas_forbidden','Privacy operator and a bounded erasure reason required.','اپراتور حریم خصوصی و دلیل محدود حذف لازم است.',403);return self::transaction(function() use ($reason,$wpdb) { $rows=$wpdb->get_results($wpdb->prepare('SELECT id FROM '.self::table('submissions')." WHERE retain_until<=%s AND encrypted_payload IS NOT NULL ORDER BY retain_until LIMIT 25 FOR UPDATE",DB::now()));foreach ($rows as $row) { if ($wpdb->update(self::table('submissions'),['encrypted_payload'=>null,'state'=>'erased'],['id'=>$row->id])!==1) throw new RuntimeException('erase');self::audit(0,'event.attendee_erase',$row->id,$reason); }return ['erased'=>count($rows),'financial_records_changed'=>false]; });
    }
    public static function permission($r) { return is_user_logged_in()&&wp_verify_nonce((string)$r->get_header('X-WP-Nonce'),'wp_rest'); }
