    public static function routes() {
        foreach (['event-series'=>'generate','event-data-policies'=>'save_policy','event-attendee-forms'=>'save_form'] as $path=>$method) register_rest_route('agency/v1','/'.$path,['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) use ($method) { $body=$r->get_json_params();return self::response(is_array($body)?self::$method($body,(string)$r->get_header('Idempotency-Key')):self::error('atlas_invalid_request','JSON object required.','اطلاعات ساختاری لازم است.')); }]);
        foreach (['event-data-policies'=>'review_policy','event-attendee-forms'=>'review_form','event-attendee-submissions'=>'review_submission'] as $path=>$method) register_rest_route('agency/v1','/'.$path.'/(?P<id>[a-f0-9-]{36})/review',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) use ($method) { $body=$r->get_json_params();return self::response(is_array($body)?self::$method($r['id'],$body,(string)$r->get_header('Idempotency-Key')):self::error('atlas_invalid_request','JSON object required.','اطلاعات ساختاری لازم است.')); }]);
        register_rest_route('agency/v1','/event-occurrences/(?P<id>[a-f0-9-]{36})/attendee-schema',['methods'=>'GET','permission_callback'=>'__return_true','callback'=>static fn($r)=>self::response(self::schema($r['id']))]);
        register_rest_route('agency/v1','/event-occurrences/(?P<id>[a-f0-9-]{36})/attendee-submissions',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $body=$r->get_json_params();return self::response(is_array($body)?self::submit($r['id'],$body,(string)$r->get_header('Idempotency-Key')):self::error('atlas_invalid_request','JSON object required.','اطلاعات ساختاری لازم است.')); }]);
        register_rest_route('agency/v1','/event-attendee-submissions/(?P<id>[a-f0-9-]{36})',['methods'=>'GET','permission_callback'=>[__CLASS__,'permission'],'callback'=>static fn($r)=>self::response((string)$r->get_param('state_only')==='1'?self::submission_status($r['id']):self::read_submission($r['id']))]);
        register_rest_route('agency/v1','/event-attendee-submissions/(?P<id>[a-f0-9-]{36})/operations-read',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $body=$r->get_json_params();if (!is_array($body)||array_keys($body)!==['purpose']||$body['purpose']!=='event_operations') return self::error('atlas_forbidden','An explicit operations purpose is required.','هدف مشخص عملیات لازم است.',403);return self::response(self::read_submission($r['id'],'event_operations')); }]);
        register_rest_route('agency/v1','/event-attendee-retention/purge',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>static function($r) { $body=$r->get_json_params();return self::response(is_array($body)&&array_keys($body)===['reason']?self::purge_due($body['reason']):self::error('atlas_invalid_request','An erasure reason is required.','دلیل حذف لازم است.')); }]);
    }
