            foreach (['policies'=>'review_policy','forms'=>'review_form'] as $table=>$op) { $rows=$wpdb->get_results('SELECT id,owner_id,state,payload FROM '.self::table($table)." WHERE state='draft' ORDER BY created_at LIMIT 25");foreach ($rows as $row) { $data=json_decode($row->payload,true);$html.='<article><h4><bdi>'.esc_html($row->id).'</bdi> · '.esc_html($table).'</h4><p>'.esc_html(self::t($data['purpose_en'],$data['purpose_fa'])).'</p><p>'.esc_html(implode(', ',$data['allowed_fields']??$data['fields']??[])).'</p>'.self::form_open($op,['id'=>$row->id]).'<label>'.esc_html(self::t('Decision','تصمیم')).'<select name="decision"><option value="approved">'.esc_html(self::t('Approve internal reviewed configuration','تأیید پیکربندی بازبینی‌شده داخلی')).'</option><option value="rejected">'.esc_html(self::t('Reject','رد')).'</option></select></label>'.self::field('evidence_reference',self::t('Actual review evidence reference','مرجع واقعی شواهد بازبینی')).self::field('reason',self::t('Review reason','دلیل بازبینی')).'<button>'.esc_html(self::t('Record independent review','ثبت بازبینی مستقل')).'</button></form></article>'; } }
