        switch ($op) {case 'generate':$result=self::generate($body,$key);break;case 'save_policy':$result=self::save_policy($body,$key);break;case 'save_form':$result=self::save_form($body,$key);break;case 'review_policy':$result=self::review_policy($id,$body,$key);break;case 'review_form':$result=self::review_form($id,$body,$key);break;case 'review_submission':$result=self::review_submission($id,$body,$key);break;case 'purge':$result=self::purge_due($body['reason']??'');break;default:$result=self::error('atlas_invalid_request','Unknown operation.','عملیات ناشناخته است.'); }if (is_wp_error($result)) wp_die(esc_html($result->get_error_message()),'',['response'=>(int)($result->get_error_data()['status']??422)]);wp_safe_redirect(add_query_arg(['atlas_area'=>'portal','lang'=>($_POST['lang']??'')==='fa'?'fa':'en','event_advanced_occ'=>$body['occurrence_id']??$body['template_id']??''],home_url('/')));exit;
